// src/components/HowToSignUp.js
import React, { useState } from 'react';

const HowToSignUp = () => {
  const [selectedType, setSelectedType] = useState(null);
  const [gearChecklist, setGearChecklist] = useState({
    swim: false,
    bike: false,
    run: false,
    nutrition: false
  });

  const handleTypeSelect = (type) => {
    setSelectedType(type);
  };

  const handleChecklistChange = (item) => {
    setGearChecklist({ ...gearChecklist, [item]: !gearChecklist[item] });
  };

  const renderRaceTips = () => {
    switch (selectedType) {
      case "Sprint":
        return "Focus on shorter training sessions, aiming for balanced practice.";
      case "Olympic":
        return "Build endurance and focus on a moderate training plan.";
      case "Half Ironman":
        return "Requires strong endurance; practice long-distance transitions.";
      case "Ironman":
        return "Consult a coach for advanced prep; prioritize nutrition and pacing.";
      default:
        return "Select a race type to see tailored tips.";
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial, sans-serif' }}>
      <h1 style={{ textAlign: 'center' }}>How to Sign Up for a Triathlon</h1>
      <div className="progress-bar">
        <div className={`progress progress-${selectedType ? '50' : '0'}`}></div>
      </div>

      <h2>1. Choose Your Triathlon Type</h2>
      <p>Select the type of race you’re interested in to see specific tips:</p>
      <div className="race-selector">
        {["Sprint", "Olympic", "Half Ironman", "Ironman"].map((type) => (
          <div
            key={type}
            className={`race-card ${selectedType === type ? 'selected' : ''}`}
            onClick={() => handleTypeSelect(type)}
          >
            <h3>{type}</h3>
            {selectedType === type && (
              <p className="race-details">{renderRaceTips()}</p>
            )}
          </div>
        ))}
      </div>

      <h2>2. Register for the Event</h2>
      <p>
        Visit <a href="https://www.active.com" target="_blank" rel="noopener noreferrer">Active.com</a> or <a href="https://www.ironman.com" target="_blank" rel="noopener noreferrer">Ironman</a> to find and register for events.
      </p>

      <h2>3. Gear Checklist</h2>
      <p>Check off each item as you prepare:</p>
      <ul>
        <li>
          <input type="checkbox" checked={gearChecklist.swim} onChange={() => handleChecklistChange("swim")} />
          <strong> Swim Gear:</strong> Wetsuit, goggles, swim cap
        </li>
        <li>
          <input type="checkbox" checked={gearChecklist.bike} onChange={() => handleChecklistChange("bike")} />
          <strong> Bike Gear:</strong> Bike, helmet, shoes
        </li>
        <li>
          <input type="checkbox" checked={gearChecklist.run} onChange={() => handleChecklistChange("run")} />
          <strong> Running Gear:</strong> Shoes, race belt, tri-suit
        </li>
        <li>
          <input type="checkbox" checked={gearChecklist.nutrition} onChange={() => handleChecklistChange("nutrition")} />
          <strong> Nutrition:</strong> Energy gels, electrolyte drinks
        </li>
      </ul>

      <h2>4. Preparing for Race Day</h2>
      <p>Practice each stage, focusing on smooth transitions.</p>
      <div className="video-section">
        <p>Watch this <a href="https://www.youtube.com/" target="_blank" rel="noopener noreferrer">Transition Tips video</a> for extra help.</p>
      </div>

      <h2>5. FAQs</h2>
      <div className="faq-section">
        <details>
          <summary>What should I wear during a triathlon?</summary>
          <p>A tri-suit is recommended for easy transition between stages.</p>
        </details>
        <details>
          <summary>Can beginners try an Ironman?</summary>
          <p>It’s possible, but extensive training is crucial for safety and success.</p>
        </details>
        <details>
          <summary>What if I need to stop during the race?</summary>
          <p>Rest stations are available; listen to your body and stay hydrated.</p>
        </details>
      </div>

      <h2>6. Mini Quiz</h2>
      <p>Test your knowledge on triathlon basics!</p>
      <div className="quiz-section">
        <p>1. Which triathlon type is best for beginners?</p>
        <button onClick={() => alert(selectedType === 'Sprint' ? "Correct!" : "Try again!")}>Sprint</button>
        <button onClick={() => alert("Try again!")}>Olympic</button>
        <button onClick={() => alert("Try again!")}>Half Ironman</button>
        <button onClick={() => alert("Try again!")}>Ironman</button>
      </div>

      <style>
        {`
          .progress-bar { margin: 10px 0; height: 5px; background: #ddd; }
          .progress { height: 5px; transition: width 0.3s; }
          .progress-0 { width: 0%; background: #76c7c0; }
          .progress-50 { width: 50%; background: #76c7c0; }
          .race-selector { display: flex; gap: 15px; flex-wrap: wrap; margin: 20px 0; }
          .race-card { border: 1px solid #ccc; padding: 15px; width: 150px; border-radius: 8px; cursor: pointer; transition: transform 0.3s; }
          .race-card.selected { background: #e0f7fa; transform: scale(1.05); }
          .race-details { margin-top: 10px; font-size: 14px; }
          .faq-section details { margin-top: 10px; }
          .faq-section summary { cursor: pointer; font-weight: bold; }
          .quiz-section { margin-top: 15px; }
          .quiz-section button { margin: 5px; padding: 8px 15px; cursor: pointer; }
        `}
      </style>
    </div>
  );
};

export default HowToSignUp;
